const root = document.getElementById('viewRoot');
let apiBase = localStorage.getItem('nexus-api-url') || window.NEXUS_API_URL || new URLSearchParams(window.location.search).get('api') || '';
let accessToken = localStorage.getItem('nexus-access-token') || '';
let liveMode = Boolean(apiBase && accessToken);
let liveSocket = null;
let tenantInfo = {company:'AutoCarga Logística',plan:'Enterprise',renewal:'15 de dezembro de 2026',users:18,vehicles:48,vehicleLimit:100,integrations:3};
const viewNames = {dashboard:'Visão geral',tracking:'Rastreamento',blocker:'Bloqueador',vehicles:'Veículos',drivers:'Motoristas',equipment:'Equipamentos',integrations:'Central de integrações',clients:'Clientes',reports:'Relatórios',billing:'Plano e cobrança'};
const statusLabel = {online:'Online',stopped:'Parado',alert:'Alerta'};
let blockerStates = JSON.parse(localStorage.getItem('nexus-blocker-states') || 'null') || Object.fromEntries(demoVehicles.map((v,index)=>[v.id,{installed:index<5,armed:index!==3,command:index===2?'pending':'ready',last:index===2?'há 3 min':'há 1 h'}]));

function escapeHtml(value){return String(value).replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));}
function toast(title, message){const node=document.createElement('div');node.className='toast';node.innerHTML=`<strong>${title}</strong><span>${message}</span>`;document.getElementById('toastRegion').appendChild(node);setTimeout(()=>node.remove(),3600)}
function apiEndpoint(path){return `${apiBase.replace(/\/$/,'')}${path}`;}
async function apiRequest(path, options={}){
  if(!apiBase) throw new Error('Backend não configurado');
  const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};
  if(accessToken) headers.Authorization=`Bearer ${accessToken}`;
  const response=await fetch(apiEndpoint(path),{...options,headers});
  const text=await response.text();
  let payload=null;
  try{payload=text?JSON.parse(text):null}catch{payload=text;}
  if(!response.ok){const message=payload?.message||payload?.error||`HTTP ${response.status}`;throw new Error(message);}
  return payload;
}
function relativeTime(value){if(!value)return 'nunca';const seconds=Math.max(0,Math.round((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return 'agora';if(seconds<3600)return `há ${Math.round(seconds/60)} min`;return `há ${Math.round(seconds/3600)} h`;}
function statusFromApi(vehicle, position){if(position?.speed>0)return 'online';if(position||vehicle.status==='INACTIVE')return 'stopped';return 'stopped';}
function updateConnectionChrome(){
  const label=document.getElementById('systemHealthLabel');
  const role=document.getElementById('profileRole');
  if(label)label.textContent=liveMode?'Sistemas operacionais':'Modo demonstração';
  if(role)role.textContent=liveMode?'Ambiente conectado':'Administradora · modo demonstração';
  document.querySelector('.health-pulse')?.classList.toggle('live',liveMode);
}
let googleMapsLoadPromise=null;
let mapCanvasSequence=0;
const demoMapCoordinates=[
  {lat:-19.9167,lng:-44.0841},{lat:-19.9012,lng:-44.0538},{lat:-19.9368,lng:-44.0281},
  {lat:-19.8844,lng:-44.0762},{lat:-19.9701,lng:-44.1158},{lat:-19.9487,lng:-44.0614}
];
function googleMapsKey(){return window.NEXUS_GOOGLE_MAPS_KEY||localStorage.getItem('nexus-google-maps-key')||'';}
function loadGoogleMapsApi(){
  if(window.google?.maps)return Promise.resolve(window.google.maps);
  if(googleMapsLoadPromise)return googleMapsLoadPromise;
  const key=googleMapsKey();
  if(!key)return Promise.reject(new Error('Chave do Google Maps não configurada.'));
  googleMapsLoadPromise=new Promise((resolve,reject)=>{
    const callback=`__nexusGoogleMapsReady${Date.now()}`;
    const script=document.createElement('script');
    window[callback]=()=>{delete window[callback];resolve(window.google.maps);};
    script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&loading=async&callback=${callback}`;
    script.async=true;script.defer=true;script.onerror=()=>{delete window[callback];googleMapsLoadPromise=null;reject(new Error('Não foi possível carregar o Google Maps.'));};
    document.head.appendChild(script);
  });
  return googleMapsLoadPromise;
}
function mapPoint(vehicle,index){const lat=Number(vehicle.latitude),lng=Number(vehicle.longitude);return Number.isFinite(lat)&&Number.isFinite(lng)?{lat,lng}:demoMapCoordinates[index%demoMapCoordinates.length];}
function mountGoogleMaps(){
  const key=googleMapsKey();
  if(!key)return;
  loadGoogleMapsApi().then(maps=>{
    document.querySelectorAll('[data-google-map]').forEach(canvas=>{
      if(canvas.__nexusGoogleMap)return;
      const wrapper=canvas.closest('.map-wrap');
      const points=demoVehicles.map((vehicle,index)=>({vehicle,position:mapPoint(vehicle,index)}));
      const map=new maps.Map(canvas,{center:points[0]?.position||{lat:-19.9167,lng:-44.0841},zoom:11,mapTypeControl:false,streetViewControl:false,fullscreenControl:true,gestureHandling:'greedy'});
      canvas.__nexusGoogleMap=map;wrapper?.classList.add('google-map-active');
      points.forEach(({vehicle,position})=>{const marker=new maps.Marker({map,position,title:`${vehicle.name} · ${vehicle.plate}`});marker.addListener('click',()=>openVehicle(vehicle.id));});
      wrapper?.querySelector('[data-map-mode="satellite"]')?.addEventListener('click',()=>map.setMapTypeId('satellite'));
      wrapper?.querySelector('[data-map-mode="roadmap"]')?.addEventListener('click',()=>map.setMapTypeId('roadmap'));
    });
  }).catch(error=>{if(document.querySelector('[data-google-map]'))toast('Google Maps',error.message);});
}
function configureGoogleMaps(){const current=googleMapsKey();const key=window.prompt('Cole a chave do Google Maps JavaScript API. Restrinja a chave ao domínio do sistema no Google Cloud.',current);if(key===null)return;if(key.trim()){localStorage.setItem('nexus-google-maps-key',key.trim());googleMapsLoadPromise=null;render();toast('Google Maps configurado','O mapa será carregado com a chave informada.');}else{localStorage.removeItem('nexus-google-maps-key');googleMapsLoadPromise=null;render();toast('Google Maps desativado','O mapa voltou ao modo de demonstração.');}}
function applyLiveData({vehicles:apiVehicles,positions,integrations:apiIntegrations,blockers,tenant}){
  const positionByVehicle=new Map((positions||[]).map(position=>[position.vehicleId,position]));
  const mapped=(apiVehicles||[]).map(vehicle=>{
    const position=positionByVehicle.get(vehicle.id);
    return {id:vehicle.id,name:vehicle.model||vehicle.brand||vehicle.plate,plate:vehicle.plate,brand:vehicle.brand||'',model:vehicle.model||'',year:vehicle.year||'',color:vehicle.color||'',type:vehicle.type||'',latitude:position?.latitude??null,longitude:position?.longitude??null,client:tenant?.name||'Organização ativa',driver:vehicle.driverName||'—',driverPhone:vehicle.driverPhone||'',driverLicense:vehicle.driverLicense||'',driverLicenseCategory:vehicle.driverLicenseCategory||'',driverLicenseExpiresAt:vehicle.driverLicenseExpiresAt||'',photoUrl:vehicle.photoUrl||'',device:vehicle.device||null,status:statusFromApi(vehicle,position),speed:Number(position?.speed||0),location:position?.address||'Sem posição recebida',time:relativeTime(position?.capturedAt),equipment:vehicle.device?.serialNumber||vehicle.device?.imei||'—'};
  });
  if(mapped.length)demoVehicles.splice(0,demoVehicles.length,...mapped);
  if(apiIntegrations)integrations=apiIntegrations.map(item=>({id:item.id,name:item.name,provider:item.provider,protocol:item.protocol,last:relativeTime(item.lastSyncAt),vehicles:0,on:item.enabled,health:item.enabled?'Saudável':'Atenção',baseUrl:item.baseUrl||''}));
  if(blockers){blockerStates={};blockers.forEach(item=>{const vehicleId=item.vehicle?.id;if(vehicleId)blockerStates[vehicleId]={installed:item.installed,armed:item.installed,command:'ready',last:relativeTime(item.lastCommunication)};});}
  if(tenant){tenantInfo={...tenantInfo,company:tenant.name||tenantInfo.company,plan:tenant.plan||tenantInfo.plan,vehicles:tenant._count?.vehicles??mapped.length,users:tenant._count?.users??tenantInfo.users,integrations:tenant._count?.integrations??integrations.length,vehicleLimit:tenant.subscription?.vehicleLimit||tenantInfo.vehicleLimit};}
  liveMode=true;localStorage.setItem('nexus-api-url',apiBase);updateConnectionChrome();
}
async function loadLiveData({notify=false}={}){
  if(!apiBase||!accessToken)return false;
  try{
    const [tenant,vehicles,positions,apiIntegrations,blockers]=await Promise.all([apiRequest('/api/tenant'),apiRequest('/api/vehicles'),apiRequest('/api/positions/latest'),apiRequest('/api/integrations'),apiRequest('/api/blockers')]);
    applyLiveData({tenant,vehicles,positions,integrations:apiIntegrations,blockers});
    render();
    if(notify)toast('Dados atualizados','Frota, posições e integrações foram carregadas da API.');
    connectWebSocket();
    return true;
  }catch(error){if(notify)toast('Falha ao atualizar',error.message);return false;}
}
function connectWebSocket(){
  if(!liveMode||!apiBase||!accessToken||liveSocket)return;
  try{const wsBase=apiBase.replace(/^http/,'ws');liveSocket=new WebSocket(`${wsBase.replace(/\/$/,'')}/ws?token=${encodeURIComponent(accessToken)}`);liveSocket.onmessage=event=>{try{const message=JSON.parse(event.data);if(message.type==='position.updated')void loadLiveData();}catch{}};liveSocket.onclose=()=>{liveSocket=null;};}catch{liveSocket=null;}
}
function metric(icon,label,value,note,cls=''){return `<article class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-note ${cls}">${note}</div></article>`}
function vehicleRows(list=demoVehicles){return list.map(v=>`<tr data-vehicle-row="${v.id}"><td><div class="vehicle-name">${v.photoUrl?`<img class="vehicle-avatar-image" src="${escapeHtml(v.photoUrl)}" alt="" />`:'<span class="vehicle-avatar">▰</span>'}<div>${escapeHtml(v.name)}<span class="vehicle-id">${escapeHtml(v.id)} · ${escapeHtml(v.plate)}</span></div></div></td><td>${escapeHtml(v.client)}</td><td>${escapeHtml(v.driver)}</td><td><span class="status-pill ${v.status}">${statusLabel[v.status]}</span></td><td><span class="speed">${v.speed} <small>km/h</small></span></td><td>${escapeHtml(v.location)}</td><td><button class="row-action" data-open-vehicle="${v.id}" aria-label="Abrir ${escapeHtml(v.name)}">›</button><button class="row-action" data-edit-vehicle="${v.id}" aria-label="Editar ${escapeHtml(v.name)}">✎</button><button class="row-action danger-text" data-delete-vehicle="${v.id}" aria-label="Excluir ${escapeHtml(v.name)}">×</button></td></tr>`).join('')}
function vehicleTable(){return `<section class="panel data-panel"><div class="panel-head"><div><h2>Veículos monitorados</h2><p>Posições recebidas nas últimas 24 horas</p></div><div class="table-toolbar"><label class="search-box">⌕<input id="vehicleSearch" placeholder="Buscar veículo" /></label><button class="filter-button" id="statusFilter">Todos os status⌄</button><button class="panel-link" data-view="vehicles">Ver todos</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Veículo</th><th>Cliente</th><th>Motorista</th><th>Status</th><th>Velocidade</th><th>Última localização</th><th></th></tr></thead><tbody id="vehicleTableBody">${vehicleRows()}</tbody></table></div></section>`}
function map(){const mapId=`google-map-${++mapCanvasSequence}`;const configured=Boolean(googleMapsKey());return `<section class="panel map-panel"><div class="panel-head"><div><h2>Mapa operacional</h2><p>Última posição conhecida da sua frota</p></div><button class="panel-link" data-view="tracking">Abrir rastreamento ↗</button></div><div class="map-wrap"><div class="google-map-canvas" id="${mapId}" data-google-map></div><div class="map-controls"><button class="map-control active" data-map-mode="roadmap">Mapa</button><button class="map-control" data-map-mode="satellite">Satélite</button><button class="map-control" data-configure-google-map>${configured?'Configurar Maps':'Ativar Google Maps'}</button></div>${demoVehicles.map((v,i)=>`<button class="map-vehicle ${v.status} v${i+1}" data-open-vehicle="${v.id}" aria-label="${v.name}">●<span class="vehicle-ping"></span></button>`).join('')}<div class="map-caption">${configured?(liveMode?'Google Maps · posições da API':'Google Maps · dados de demonstração'):(liveMode?'Dados recebidos pela API · WebSocket ativo':'Dados de demonstração · configure a chave do Google Maps')}</div><div class="map-legend"><span class="legend-item"><i class="legend-dot"></i>Online</span><span class="legend-item"><i class="legend-dot offline"></i>Parado</span><span class="legend-item"><i class="legend-dot alert"></i>Alerta</span></div></div></section>`}
function dashboardView(){const online=demoVehicles.filter(v=>v.status==='online').length;const stopped=demoVehicles.filter(v=>v.status==='stopped').length;const alerts=demoVehicles.filter(v=>v.status==='alert').length;return `<div class="view-content page"><div class="page-heading"><div><span class="eyebrow">Quarta-feira, 20 de novembro de 2026</span><h1>Bom dia, Marina.</h1><p>Acompanhe a operação da sua frota em um só lugar.</p></div><div class="heading-actions"><button class="button secondary" id="refreshData">↻ Atualizar dados</button><button class="button primary" data-view="tracking">◉ Abrir mapa ao vivo</button></div></div><div class="metrics-grid">${metric('▣','Veículos totais',demoVehicles.length,String(liveMode?'API conectada':'modo demonstração'),'up')}${metric('●','Online agora',online,`${demoVehicles.length?Math.round(online/demoVehicles.length*100):0}% da frota`,'up')}${metric('◌','Parados',stopped,'dentro do esperado')}${metric('⌁','Em movimento',online,'posição recebida','up')}${metric('!','Em alerta',String(alerts).padStart(2,'0'),'requer atenção')}${metric('♧','Clientes ativos',tenantInfo.company?'1':'0','tenant ativo','up')}</div><div class="dashboard-grid"><div>${map()}${vehicleTable()}</div><div class="side-stack"><section class="panel"><div class="panel-head"><div><h2>Atenção agora</h2><p>Ocorrências que pedem ação</p></div><button class="panel-link">Ver todas</button></div><div class="alert-list"><div class="alert-row"><i class="alert-status"></i><main><strong>Velocidade acima do limite</strong><span>Mercedes-Benz Actros · GKT-2J07</span></main><time class="alert-time">há 3 min</time></div><div class="alert-row"><i class="alert-status amber"></i><main><strong>Equipamento sem comunicação</strong><span>Scania P320 · LNZ-8D10</span></main><time class="alert-time">há 12 min</time></div><div class="alert-row"><i class="alert-status amber"></i><main><strong>Manutenção preventiva próxima</strong><span>Volvo VM 330 · HJF-3A91</span></main><time class="alert-time">hoje</time></div></div></section><section class="panel"><div class="panel-head"><div><h2>Atividade recente</h2><p>Eventos do seu ambiente</p></div><button class="panel-link">Histórico</button></div><div class="activity-list"><div class="activity-row"><i class="activity-marker">↗</i><main><strong>Rota iniciada</strong><span>Volvo FH 540 · há 4 min</span></main></div><div class="activity-row"><i class="activity-marker">✓</i><main><strong>Integração sincronizada</strong><span>TrackPro principal · há 6 min</span></main></div><div class="activity-row"><i class="activity-marker">⌁</i><main><strong>Novo equipamento associado</strong><span>TRK-90821 · há 32 min</span></main></div></div></section></div></div></div>`}
function trackingView(){return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Operação em tempo real</span><h1>Rastreamento</h1><p>Posições atualizadas automaticamente a cada 30 segundos.</p></div><div class="heading-actions"><button class="button secondary" id="centerMap">⌖ Centralizar frota</button><button class="button primary" id="simulatePosition">↻ Simular atualização</button></div></div><div class="tracking-layout">${map()}<section class="panel"><div class="panel-head"><div><h2>Frota ativa</h2><p>${demoVehicles.filter(v=>v.status==='online').length} veículos transmitindo agora</p></div></div><div class="alert-list">${demoVehicles.map(v=>`<button class="alert-row vehicle-select" data-open-vehicle="${v.id}"><i class="alert-status ${v.status==='online'?'':'amber'}"></i><main><strong>${v.name}</strong><span>${v.plate} · ${v.location}</span></main><span class="speed">${v.speed} km/h</span></button>`).join('')}</div></section></div></div>`}
function blockerCards(){return demoVehicles.map(v=>{const device=blockerStates[v.id]||{installed:false,armed:false,command:'unavailable',last:'—'};const state=!device.installed?'Sem dispositivo':device.command==='pending'?'Comando pendente':device.armed?'Pronto para comando':'Bloqueado';const tone=!device.installed?'muted':device.command==='pending'?'amber':device.armed?'green':'red';return `<article class="blocker-card"><div class="blocker-vehicle-icon ${tone}">⬢</div><div class="blocker-info"><div class="blocker-title"><h3>${v.name}</h3><span class="blocker-state ${tone}">${state}</span></div><p>${v.plate} · ${v.id} · ${device.installed?'Módulo BLK-4G':'Nenhum módulo associado'}</p><div class="blocker-meta"><span>Último comando: ${device.last}</span><span>Motorista: ${v.driver}</span></div></div><div class="blocker-actions">${device.installed?`<button class="button ${device.armed?'danger':'secondary'}" data-command-blocker="${v.id}" data-command-action="${device.armed?'block':'release'}">${device.armed?'Enviar bloqueio':'Liberar veículo'}</button>`:'<button class="button secondary" data-view="equipment">Associar módulo</button>'}<button class="row-action" data-blocker-history="${v.id}" title="Ver histórico">⋮</button></div></article>`}).join('')}
function blockerView(){const installed=Object.values(blockerStates).filter(s=>s.installed).length;const ready=Object.values(blockerStates).filter(s=>s.installed&&s.armed).length;const pending=Object.values(blockerStates).filter(s=>s.command==='pending').length;return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Comandos críticos</span><h1>Bloqueador</h1><p>Controle remoto de imobilização com dupla confirmação e trilha de auditoria.</p></div><div class="heading-actions"><button class="button secondary" id="blockerAudit">▤ Ver auditoria</button><button class="button primary" id="blockerRefresh">↻ Atualizar status</button></div></div><div class="safety-banner"><span class="safety-icon">!</span><div><strong>${liveMode?'Ambiente conectado':'Ambiente de demonstração'}</strong><p>${liveMode?'Os comandos serão enviados ao adaptador configurado e registrados na auditoria.':'Os comandos abaixo não acionam veículos reais. Conecte a API para enviar comandos ao provedor do dispositivo.'}</p></div><span class="safety-tag">${liveMode?'API':'SIMULADO'}</span></div><div class="blocker-summary"><div class="summary-card green"><strong>${installed}</strong><span>Módulos instalados</span></div><div class="summary-card"><strong>${ready}</strong><span>Prontos para comando</span></div><div class="summary-card amber"><strong>${pending}</strong><span>Comandos pendentes</span></div><div class="summary-card"><strong>${demoVehicles.length-installed}</strong><span>Sem bloqueador</span></div></div><div class="blocker-layout"><section><div class="panel-head" style="padding:0 0 12px"><div><h2>Dispositivos por veículo</h2><p>O estado é sincronizado pelo adaptador de bloqueador do tenant.</p></div></div><div id="blockerList">${blockerCards()}</div></section><aside class="side-info"><h3>Regras de segurança</h3><p>O bloqueador é uma ação operacional sensível. A API aplica as mesmas regras em qualquer canal.</p><div class="check-row"><i class="check">✓</i><div><strong>Permissão por função</strong><span>Somente administradores e operadores autorizados.</span></div></div><div class="check-row"><i class="check">✓</i><div><strong>Dupla confirmação</strong><span>Placa, motorista e motivo antes do envio.</span></div></div><div class="check-row"><i class="check">✓</i><div><strong>Auditoria imutável</strong><span>Usuário, horário, provedor e resposta registrados.</span></div></div><button class="button secondary" style="width:100%;justify-content:center;margin-top:8px" id="blockerDocs">Ver contrato do adaptador</button></aside></div></div>`}
function billingView(){const vehicleUse=Math.min(100,Math.round((tenantInfo.vehicles/tenantInfo.vehicleLimit)*100));return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Conta da organização</span><h1>Plano e cobrança</h1><p>Administre o uso do tenant ${escapeHtml(tenantInfo.company)} e as permissões da equipe.</p></div><div class="heading-actions"><button class="button secondary" id="refreshBilling">↻ Atualizar</button><button class="button primary" id="contactBilling">Falar com o atendimento</button></div></div><div class="saas-hero"><div><span class="eyebrow">Plano atual</span><h2>${escapeHtml(tenantInfo.plan)}</h2><p>Operação completa para empresas que precisam escalar rastreamento, comandos e integrações.</p><div class="heading-actions"><button class="button primary" id="billingCheckout">Assinar plano</button><button class="button secondary" id="billingPortal">Abrir portal</button></div></div><div class="saas-price"><strong>R$ 1.490</strong><span>/ mês</span><small>Próxima cobrança em ${tenantInfo.renewal}</small></div></div><div class="billing-grid"><section class="panel usage-panel"><div class="panel-head"><div><h2>Uso do tenant</h2><p>Limites aplicados somente à organização ativa.</p></div></div><div class="usage-row"><div><strong>Veículos</strong><span>${tenantInfo.vehicles} de ${tenantInfo.vehicleLimit}</span></div><div class="usage-bar"><i style="width:${vehicleUse}%"></i></div></div><div class="usage-row"><div><strong>Usuários</strong><span>${tenantInfo.users} ativos</span></div><div class="usage-bar"><i style="width:36%"></i></div></div><div class="usage-row"><div><strong>Integrações</strong><span>${tenantInfo.integrations} conectadas</span></div><div class="usage-bar"><i style="width:60%"></i></div></div></section><section class="panel"><div class="panel-head"><div><h2>Recursos incluídos</h2><p>Disponíveis para esta empresa</p></div></div><div class="feature-list"><span>✓ Rastreamento em tempo real</span><span>✓ Bloqueador e comandos remotos</span><span>✓ Central de integrações</span><span>✓ Usuários e permissões por função</span><span>✓ Relatórios e auditoria</span></div></section></div></div>`}
function vehiclesView(){return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Cadastro e operação</span><h1>Veículos</h1><p>Gerencie os veículos, motoristas e vínculos da sua frota.</p></div><div class="heading-actions"><button class="button secondary">⇩ Exportar</button><button class="button primary" id="newVehicle">+ Novo veículo</button></div></div>${vehicleTable()}</div>`}
function integrationsView(){return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Conectividade</span><h1>Central de integrações</h1><p>Conecte fornecedores e normalize os dados da sua operação.</p></div><button class="button primary" id="newIntegration">+ Adicionar integração</button></div><div class="integration-summary"><div class="summary-card green"><strong>${integrations.filter(i=>i.on).length}</strong><span>Integrações ativas</span></div><div class="summary-card"><strong>${integrations.reduce((a,i)=>a+i.vehicles,0)}</strong><span>Veículos sincronizados</span></div><div class="summary-card"><strong>30s</strong><span>Última atualização média</span></div><div class="summary-card amber"><strong>${integrations.filter(i=>!i.on).length}</strong><span>Precisam de atenção</span></div></div><div class="integration-layout"><section><div class="panel-head" style="padding:0 0 12px"><div><h2>Fornecedores conectados</h2><p>Credenciais e configurações ficam protegidas no backend.</p></div></div><div id="integrationList">${integrationCards()}</div></section><aside class="side-info"><h3>Arquitetura de adaptadores</h3><p>Cada fornecedor usa um adaptador próprio para converter posições, eventos e comandos em um formato único do Nexus.</p><div class="check-row"><i class="check">✓</i><div><strong>REST e webhooks</strong><span>Conecte APIs modernas sem acoplamento.</span></div></div><div class="check-row"><i class="check">✓</i><div><strong>TCP e UDP prontos</strong><span>Prepare protocolos legados e proprietários.</span></div></div><div class="check-row"><i class="check">✓</i><div><strong>Segredos protegidos</strong><span>Tokens não são exibidos no frontend.</span></div></div><button class="button secondary" style="width:100%;justify-content:center;margin-top:8px" id="viewAdapterDocs">Ver documentação do adaptador</button></aside></div></div>`}
function integrationCards(){return integrations.map(i=>`<article class="integration-card"><div class="integration-logo">${i.provider.slice(0,2).toUpperCase()}</div><div class="integration-info"><h3>${escapeHtml(i.name)}</h3><p>${escapeHtml(i.provider)} · ${i.protocol}</p><div class="integration-meta"><span>◉ ${i.vehicles} veículos</span><span>↻ ${i.last}</span></div></div><div class="integration-state"><span class="state-text" style="color:${i.on?'var(--green)':'var(--amber)'}">${i.on?'Saudável':'Atenção'}</span><button class="switch ${i.on?'on':''}" data-toggle-integration="${i.id}" aria-label="Ativar ou desativar"></button><button class="row-action" data-test-integration="${i.id}" title="Testar conexão">⋮</button></div></article>`).join('')}
function openDriverModal(vehicleId=null){const form=document.getElementById('driverForm');const vehicle=vehicleId?demoVehicles.find(item=>String(item.id)===String(vehicleId)):null;const select=document.getElementById('driverVehicleSelect');form.reset();form.dataset.vehicleId=vehicle?.id||'';select.innerHTML=demoVehicles.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)} · ${escapeHtml(item.plate)}</option>`).join('');document.getElementById('driverModalTitle').textContent=vehicle?'Editar motorista':'Novo motorista';if(vehicle){for(const [key,value] of Object.entries({driverName:vehicle.driver==='—'?'':vehicle.driver,driverPhone:vehicle.driverPhone||'',driverLicense:vehicle.driverLicense||'',driverLicenseCategory:vehicle.driverLicenseCategory||'B',driverLicenseExpiresAt:vehicle.driverLicenseExpiresAt?String(vehicle.driverLicenseExpiresAt).slice(0,10):''}))if(form.elements[key])form.elements[key].value=value;select.value=vehicle.id;}document.getElementById('driverModalBackdrop').hidden=false;document.querySelector('#driverForm input')?.focus();}
function closeDriverModal(){document.getElementById('driverModalBackdrop').hidden=true;const form=document.getElementById('driverForm');form.reset();form.dataset.vehicleId='';document.getElementById('driverModalTitle').textContent='Novo motorista';}
async function saveDriver(form){const editing=Boolean(form.dataset.vehicleId);const raw=Object.fromEntries(new FormData(form));const vehicle=demoVehicles.find(item=>String(item.id)===String(raw.vehicleId));if(!vehicle)return toast('Veículo obrigatório','Selecione o veículo que ficará vinculado ao motorista.');const payload={driverName:raw.driverName,driverPhone:raw.driverPhone||'',driverLicense:raw.driverLicense,driverLicenseCategory:raw.driverLicenseCategory||'',driverLicenseExpiresAt:raw.driverLicenseExpiresAt?new Date(`${raw.driverLicenseExpiresAt}T00:00:00.000Z`).toISOString():null};try{if(liveMode){await apiRequest(`/api/vehicles/${encodeURIComponent(vehicle.id)}`,{method:'PATCH',body:JSON.stringify(payload)});await loadLiveData();}else{Object.assign(vehicle,payload);render();}closeDriverModal();toast(editing?'Motorista atualizado':'Motorista cadastrado',`${payload.driverName} foi vinculado a ${vehicle.plate}.`);}catch(error){toast('Não foi possível salvar',error.message);}}
function clientsView(){const grouped=clients.map(client=>({...client,vehicles:demoVehicles.filter(vehicle=>vehicle.client===client.name).length||client.vehicles}));return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Gestão de contas</span><h1>Clientes</h1><p>Organizações atendidas e responsáveis pela frota.</p></div><button class="button primary" id="newClient">+ Novo cliente</button></div><div class="client-grid">${grouped.map(client=>`<article class="panel client-card"><div class="client-avatar">${escapeHtml(client.name.slice(0,2).toUpperCase())}</div><div><h2>${escapeHtml(client.name)}</h2><p>${escapeHtml(client.contact||'Contato não informado')}</p><div class="client-meta"><span>${client.vehicles} veículos</span><span class="state-text" style="color:var(--green)">${escapeHtml(client.status)}</span></div></div><button class="button secondary" data-client-filter="${escapeHtml(client.name)}">Ver frota</button></article>`).join('')}</div></div>`}
function driversView(){const drivers=[...new Map(demoVehicles.filter(vehicle=>vehicle.driver&&vehicle.driver!=='—').map(vehicle=>[vehicle.driver,vehicle])).values()];return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Pessoas e operação</span><h1>Motoristas</h1><p>Cadastre motorista, CNH, categoria, validade e veículo vinculado.</p></div><button class="button primary" id="newDriver">+ Cadastrar motorista</button></div><section class="panel data-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Motorista</th><th>Telefone</th><th>CNH</th><th>Categoria</th><th>Validade</th><th>Veículo vinculado</th><th>Status</th><th>Ações</th></tr></thead><tbody>${drivers.map(vehicle=>`<tr><td><strong>${escapeHtml(vehicle.driver)}</strong></td><td>${escapeHtml(vehicle.driverPhone||'Não informado')}</td><td>${escapeHtml(vehicle.driverLicense||'Não informado')}</td><td>${escapeHtml(vehicle.driverLicenseCategory||'—')}</td><td>${vehicle.driverLicenseExpiresAt?new Date(vehicle.driverLicenseExpiresAt).toLocaleDateString('pt-BR'):'—'}</td><td>${escapeHtml(vehicle.name)} · ${escapeHtml(vehicle.plate)}</td><td><span class="status-pill ${vehicle.status}">${statusLabel[vehicle.status]}</span></td><td><button class="row-action" data-edit-driver="${vehicle.id}" aria-label="Editar ${escapeHtml(vehicle.driver)}">✎</button><button class="row-action danger-text" data-delete-driver="${vehicle.id}" aria-label="Excluir ${escapeHtml(vehicle.driver)}">×</button></td></tr>`).join('')||'<tr><td colspan="8">Nenhum motorista cadastrado.</td></tr>'}</tbody></table></div></section></div>`}
function equipmentView(){const installed=demoVehicles.filter(vehicle=>vehicle.equipment&&vehicle.equipment!=='—');return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Telemetria e segurança</span><h1>Equipamentos</h1><p>Dispositivos GPS, IMEI, comunicação e vínculo com a frota.</p></div><button class="button primary" id="newDevice">+ Associar equipamento</button></div><section class="panel data-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Equipamento</th><th>Veículo</th><th>IMEI / serial</th><th>Última comunicação</th><th>Status</th></tr></thead><tbody>${installed.map(vehicle=>`<tr><td><strong>${escapeHtml(vehicle.equipment)}</strong></td><td>${escapeHtml(vehicle.name)} · ${escapeHtml(vehicle.plate)}</td><td>${escapeHtml(vehicle.device?.imei||vehicle.device?.serialNumber||'Não informado')}</td><td>${escapeHtml(vehicle.time)}</td><td><span class="status-pill ${vehicle.status}">${statusLabel[vehicle.status]}</span></td></tr>`).join('')||'<tr><td colspan="5">Nenhum equipamento associado.</td></tr>'}</tbody></table></div></section></div>`}
function reportsView(){const online=demoVehicles.filter(vehicle=>vehicle.status==='online').length;const alerts=demoVehicles.filter(vehicle=>vehicle.status==='alert').length;return `<div class="view-content page"><div class="view-topline"><div><span class="eyebrow">Indicadores operacionais</span><h1>Relatórios</h1><p>Resumo exportável da operação atual do tenant.</p></div><button class="button primary" id="exportReport">⇩ Exportar CSV</button></div><div class="metrics-grid">${metric('▣','Veículos',demoVehicles.length,'cadastrados')}${metric('●','Online',online,'transmitindo','up')}${metric('!','Alertas',alerts,'requerem atenção')}${metric('♙','Motoristas',new Set(demoVehicles.map(vehicle=>vehicle.driver).filter(driver=>driver!=='—')).size,'vinculados')}</div><section class="panel data-panel"><div class="panel-head"><div><h2>Posição da frota</h2><p>Dados atuais por veículo</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Veículo</th><th>Status</th><th>Velocidade</th><th>Localização</th><th>Último sinal</th></tr></thead><tbody>${demoVehicles.map(vehicle=>`<tr><td>${escapeHtml(vehicle.name)} · ${escapeHtml(vehicle.plate)}</td><td>${statusLabel[vehicle.status]}</td><td>${vehicle.speed} km/h</td><td>${escapeHtml(vehicle.location)}</td><td>${escapeHtml(vehicle.time)}</td></tr>`).join('')}</tbody></table></div></section></div>`}
function exportReport(){const header=['Veículo','Placa','Motorista','Status','Velocidade','Localização','Último sinal'];const rows=demoVehicles.map(vehicle=>[vehicle.name,vehicle.plate,vehicle.driver,statusLabel[vehicle.status],vehicle.speed,vehicle.location,vehicle.time]);const csv=[header,...rows].map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(';')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([`\ufeff${csv}`],{type:'text/csv;charset=utf-8'}));link.download=`nexus-fleet-relatorio-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(link.href);toast('Relatório exportado','O arquivo CSV foi baixado.');}
function render(){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));document.getElementById('breadcrumbCurrent').textContent=viewNames[currentView];root.innerHTML=currentView==='dashboard'?dashboardView():currentView==='tracking'?trackingView():currentView==='blocker'?blockerView():currentView==='vehicles'?vehiclesView():currentView==='drivers'?driversView():currentView==='equipment'?equipmentView():currentView==='integrations'?integrationsView():currentView==='clients'?clientsView():currentView==='reports'?reportsView():currentView==='billing'?billingView():dashboardView();bindView();}
function openVehicleModal(vehicleId=null){const form=document.getElementById('vehicleForm');const vehicle=vehicleId?demoVehicles.find(item=>String(item.id)===String(vehicleId)):null;form.dataset.vehicleId=vehicle?.id||'';document.getElementById('vehicleModalTitle').textContent=vehicle?'Editar veículo':'Novo veículo';if(vehicle){for(const [key,value] of Object.entries({plate:vehicle.plate,brand:vehicle.brand||'',model:vehicle.model||vehicle.name,year:vehicle.year||'',color:vehicle.color||'',type:vehicle.type||'',driverName:vehicle.driver==='—'?'':vehicle.driver,driverPhone:vehicle.driverPhone||'',driverLicense:vehicle.driverLicense||'',driverLicenseCategory:vehicle.driverLicenseCategory||'',driverLicenseExpiresAt:vehicle.driverLicenseExpiresAt?String(vehicle.driverLicenseExpiresAt).slice(0,10):''}))if(form.elements[key])form.elements[key].value=value;const preview=document.getElementById('vehiclePhotoPreview');if(vehicle.photoUrl){preview.querySelector('img').src=vehicle.photoUrl;preview.hidden=false;}}document.getElementById('vehicleModalBackdrop').hidden=false;document.querySelector('#vehicleForm input')?.focus();}
function closeVehicleModal(){document.getElementById('vehicleModalBackdrop').hidden=true;const form=document.getElementById('vehicleForm');form.reset();form.dataset.vehicleId='';document.getElementById('vehicleModalTitle').textContent='Novo veículo';const preview=document.getElementById('vehiclePhotoPreview');if(preview){preview.hidden=true;preview.querySelector('img').removeAttribute('src');}}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file);});}
async function saveVehicle(form){
  const raw=Object.fromEntries(new FormData(form));
  const photo=raw.photo instanceof File&&raw.photo.size?raw.photo:null;
  delete raw.photo;
  const payload=Object.fromEntries(Object.entries(raw).filter(([,value])=>String(value).trim()!=='').map(([key,value])=>[key,key==='year'?Number(value):value]));
  if(photo)payload.photoUrl=await fileToDataUrl(photo);
  try{
    const vehicleId=form.dataset.vehicleId;
    if(liveMode){await apiRequest(vehicleId?`/api/vehicles/${encodeURIComponent(vehicleId)}`:'/api/vehicles',{method:vehicleId?'PATCH':'POST',body:JSON.stringify(payload)});await loadLiveData();toast(vehicleId?'Veículo atualizado':'Veículo criado',vehicleId?'As alterações foram salvas no tenant.':'O cadastro foi salvo no tenant.');}
    else if(vehicleId){const vehicle=demoVehicles.find(item=>String(item.id)===String(vehicleId));if(vehicle)Object.assign(vehicle,{...payload,name:payload.model||payload.brand||payload.plate,driver:payload.driverName||'—',photoUrl:payload.photoUrl||vehicle.photoUrl||''});render();toast('Veículo atualizado','Alterações salvas neste navegador.');}
    else{demoVehicles.push({id:`LOCAL-${Date.now()}`,name:payload.model||payload.brand||payload.plate,plate:payload.plate,client:tenantInfo.company,driver:payload.driverName||'—',driverPhone:payload.driverPhone||'',driverLicense:payload.driverLicense||'',driverLicenseCategory:payload.driverLicenseCategory||'',driverLicenseExpiresAt:payload.driverLicenseExpiresAt||'',photoUrl:payload.photoUrl||'',status:'stopped',speed:0,location:'Sem posição',time:'agora',equipment:'—'});render();toast('Veículo criado','Salvo no modo demonstração deste navegador.');}
    closeVehicleModal();
  }catch(error){toast('Não foi possível salvar',error.message);}
}
async function deleteVehicle(vehicleId){const vehicle=demoVehicles.find(item=>String(item.id)===String(vehicleId));if(!vehicle)return;if(!window.confirm(`Excluir o veículo ${vehicle.plate}?`))return;try{if(liveMode){await apiRequest(`/api/vehicles/${encodeURIComponent(vehicleId)}`,{method:'DELETE'});await loadLiveData();}else{demoVehicles.splice(demoVehicles.indexOf(vehicle),1);render();}toast('Veículo excluído',`${vehicle.plate} foi removido do cadastro.`);}catch(error){toast('Não foi possível excluir',error.message);}}
async function deleteDriver(vehicleId){const vehicle=demoVehicles.find(item=>String(item.id)===String(vehicleId));if(!vehicle)return;if(!window.confirm(`Excluir o motorista ${vehicle.driver}?`))return;const payload={driverName:'',driverPhone:'',driverLicense:'',driverLicenseCategory:'',driverLicenseExpiresAt:null};try{if(liveMode){await apiRequest(`/api/vehicles/${encodeURIComponent(vehicleId)}`,{method:'PATCH',body:JSON.stringify(payload)});await loadLiveData();}else{Object.assign(vehicle,payload);render();}toast('Motorista excluído','O vínculo do motorista e da CNH foi removido.');}catch(error){toast('Não foi possível excluir',error.message);}}
async function testIntegration(id){
  if(!liveMode)return toast('Teste local','Conecte a API para testar o fornecedor real.');
  try{const result=await apiRequest(`/api/integrations/${encodeURIComponent(id)}/test`,{method:'POST'});toast(result.ok?'Conexão saudável':'Falha na conexão',result.message||'Resposta recebida do adaptador.');await loadLiveData();}catch(error){toast('Teste falhou',error.message);}
}
async function syncIntegration(){
  if(!liveMode)return toast('Atualização local','Conecte a API para sincronizar posições reais.');
  const integration=integrations.find(item=>item.on);
  if(!integration)return toast('Nenhuma integração ativa','Ative um fornecedor antes de sincronizar.');
  try{const result=await apiRequest(`/api/integrations/${encodeURIComponent(integration.id)}/sync`,{method:'POST'});toast('Sincronização concluída',`${result.received||0} posições recebidas.`);await loadLiveData();}catch(error){toast('Sincronização falhou',error.message);}
}
function bindVehicleActions(scope=document){
  scope.querySelectorAll('[data-open-vehicle]').forEach(btn=>btn.addEventListener('click',()=>openVehicle(btn.dataset.openVehicle)));
  scope.querySelectorAll('[data-edit-vehicle]').forEach(btn=>btn.addEventListener('click',()=>openVehicleModal(btn.dataset.editVehicle)));
  scope.querySelectorAll('[data-delete-vehicle]').forEach(btn=>btn.addEventListener('click',()=>void deleteVehicle(btn.dataset.deleteVehicle)));
}
function bindView(){
  document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>{currentView=btn.dataset.view;document.getElementById('sidebar').classList.remove('open');render()}));
  bindVehicleActions();
  document.querySelectorAll('[data-configure-google-map]').forEach(btn=>btn.addEventListener('click',configureGoogleMaps));
  mountGoogleMaps();
  const search=document.getElementById('vehicleSearch');
  if(search)search.addEventListener('input',()=>{const query=search.value.toLowerCase();const body=document.getElementById('vehicleTableBody');body.innerHTML=vehicleRows(demoVehicles.filter(v=>(v.name+v.id+v.plate+v.client).toLowerCase().includes(query)));bindVehicleActions(body);});
  document.querySelectorAll('[data-edit-driver]').forEach(btn=>btn.addEventListener('click',()=>openDriverModal(btn.dataset.editDriver)));
  document.querySelectorAll('[data-delete-driver]').forEach(btn=>btn.addEventListener('click',()=>void deleteDriver(btn.dataset.deleteDriver)));
  const refresh=document.getElementById('refreshData');if(refresh)refresh.addEventListener('click',()=>loadLiveData({notify:true}).then(ok=>{if(!ok&&!liveMode)toast('Modo demonstração','Conecte o backend pelo perfil para carregar dados reais.');}));
  const simulate=document.getElementById('simulatePosition');if(simulate)simulate.addEventListener('click',syncIntegration);
  const center=document.getElementById('centerMap');if(center)center.addEventListener('click',()=>toast('Mapa centralizado','Todos os veículos ativos estão no enquadramento.'));
  const ni=document.getElementById('newIntegration');if(ni)ni.addEventListener('click',openModal);
  document.querySelectorAll('[data-toggle-integration]').forEach(btn=>btn.addEventListener('click',()=>toggleIntegration(btn.dataset.toggleIntegration)));
  document.querySelectorAll('[data-test-integration]').forEach(btn=>btn.addEventListener('click',()=>testIntegration(btn.dataset.testIntegration)));
  const docs=document.getElementById('viewAdapterDocs');if(docs)docs.addEventListener('click',()=>{if(liveMode)window.open(apiEndpoint('/api/docs'),'_blank','noopener');else toast('Documentação','Conecte a API para abrir o Swagger do backend.');});
  const nv=document.getElementById('newVehicle');if(nv)nv.addEventListener('click',openVehicleModal);
  const nd=document.getElementById('newDriver');if(nd)nd.addEventListener('click',openDriverModal);
  const ne=document.getElementById('newDevice');if(ne)ne.addEventListener('click',()=>{currentView='vehicles';render();openVehicleModal();toast('Associar equipamento','Cadastre o veículo primeiro; o vínculo GPS pode ser feito pela API de dispositivos.');});
  const nc=document.getElementById('newClient');if(nc)nc.addEventListener('click',()=>{const name=window.prompt('Nome do novo cliente:');if(!name)return;const contact=window.prompt('E-mail de contato:')||'Não informado';clients.push({id:`client-${Date.now()}`,name,contact,vehicles:0,status:'Ativo'});localStorage.setItem('nexus-clients',JSON.stringify(clients));render();toast('Cliente cadastrado',`${name} foi adicionado ao ambiente.`);});
  document.querySelectorAll('[data-client-filter]').forEach(btn=>btn.addEventListener('click',()=>{currentView='vehicles';render();const search=document.getElementById('vehicleSearch');if(search){search.value=btn.dataset.clientFilter.toLowerCase();search.dispatchEvent(new Event('input'));}}));
  const report=document.getElementById('exportReport');if(report)report.addEventListener('click',exportReport);
  document.querySelectorAll('[data-command-blocker]').forEach(btn=>btn.addEventListener('click',()=>executeBlockerCommand(btn.dataset.commandBlocker,btn.dataset.commandAction)));
  document.querySelectorAll('[data-blocker-history]').forEach(btn=>btn.addEventListener('click',()=>toast('Auditoria','Abra o veículo para consultar os últimos comandos registrados.')));
  const blockerRefresh=document.getElementById('blockerRefresh');if(blockerRefresh)blockerRefresh.addEventListener('click',()=>loadLiveData({notify:true}));
  const blockerAudit=document.getElementById('blockerAudit');if(blockerAudit)blockerAudit.addEventListener('click',()=>toast('Auditoria',liveMode?'Os comandos ficam registrados na API por veículo.':'Nenhum comando real foi enviado neste ambiente.'));
  const blockerDocs=document.getElementById('blockerDocs');if(blockerDocs)blockerDocs.addEventListener('click',()=>{if(liveMode)window.open(apiEndpoint('/api/docs'),'_blank','noopener');else toast('Contrato do adaptador','Conecte a API para abrir a documentação.');});
  const billing=document.getElementById('contactBilling');if(billing)billing.addEventListener('click',()=>toast('Atendimento','O time comercial receberá o pedido pelo canal configurado no tenant.'));
  const refreshBilling=document.getElementById('refreshBilling');if(refreshBilling)refreshBilling.addEventListener('click',()=>loadLiveData({notify:true}));
  const checkout=document.getElementById('billingCheckout');if(checkout)checkout.addEventListener('click',async()=>{if(!liveMode)return toast('Backend necessário','Conecte a API para abrir o checkout Stripe.');try{const result=await apiRequest('/api/billing/checkout',{method:'POST'});if(result.url)window.location.href=result.url;}catch(error){toast('Checkout indisponível',error.message);}});
  const portal=document.getElementById('billingPortal');if(portal)portal.addEventListener('click',async()=>{if(!liveMode)return toast('Backend necessário','Conecte a API para abrir o portal de cobrança.');try{const result=await apiRequest('/api/billing/portal',{method:'POST'});if(result.url)window.location.href=result.url;}catch(error){toast('Portal indisponível',error.message);}});
}
function openVehicle(id){selectedVehicle=demoVehicles.find(v=>v.id===id);if(!selectedVehicle)return;const v=selectedVehicle;const blocker=blockerStates[v.id]||{installed:false,armed:false,command:'unavailable',last:'—'};const drawer=document.createElement('aside');drawer.className='vehicle-drawer';drawer.id='vehicleDrawer';drawer.innerHTML=`<div class="drawer-header">${v.photoUrl?`<img class="photo-preview-image" src="${escapeHtml(v.photoUrl)}" alt="Foto de ${escapeHtml(v.name)}" />`:''}<div><span class="eyebrow">Detalhes do veículo</span><h2>${escapeHtml(v.name)}</h2><p>${escapeHtml(v.plate)} · ${escapeHtml(v.id)}</p></div><button class="drawer-close" id="closeDrawer">×</button></div><div class="drawer-status">● ${statusLabel[v.status]} <span style="float:right;font-weight:400">Último sinal ${v.time}</span></div><div class="drawer-details"><div class="detail"><label>Velocidade</label><strong>${v.speed} <small>km/h</small></strong></div><div class="detail"><label>Ignição</label><strong>${v.status==='stopped'?'Desligada':'Ligada'}</strong></div><div class="detail"><label>Motorista</label><strong style="font-size:12px">${escapeHtml(v.driver)}</strong></div><div class="detail"><label>Equipamento</label><strong style="font-size:12px">${escapeHtml(v.equipment)}</strong></div><div class="detail" style="grid-column:1/-1"><label>Última localização</label><strong style="font-size:13px">${escapeHtml(v.location)}</strong></div></div><div class="drawer-route"><span></span><span></span></div><div class="drawer-command"><div><span class="eyebrow">Bloqueador</span><strong>${blocker.installed?(blocker.armed?'Pronto para comando':'Veículo bloqueado'):'Não instalado'}</strong><small>${blocker.installed?'Módulo BLK-4G · último sinal '+blocker.last:'Associe um módulo para liberar comandos'}</small></div>${blocker.installed?`<button class="button ${blocker.armed?'danger':'secondary'}" id="drawerBlocker">${blocker.armed?'Bloquear':'Liberar'}</button>`:''}</div><button class="button primary" style="width:100%;justify-content:center;margin-top:18px" id="drawerHistory">Ver histórico de rota</button>`;document.body.appendChild(drawer);document.getElementById('closeDrawer').addEventListener('click',()=>drawer.remove());document.getElementById('drawerHistory').addEventListener('click',()=>toast('Histórico de rota',liveMode?'O histórico detalhado será carregado pela API de telemetria.':'Conecte a API para consultar o histórico real.'));const drawerBlocker=document.getElementById('drawerBlocker');if(drawerBlocker)drawerBlocker.addEventListener('click',()=>executeBlockerCommand(v.id,blocker.armed?'block':'release'));}
async function executeBlockerCommand(id,action){const vehicle=demoVehicles.find(v=>v.id===id);const device=blockerStates[id];if(!vehicle||!device?.installed)return toast('Ação indisponível','Este veículo não possui um módulo bloqueador associado.');const isBlocking=action==='block';const approved=window.confirm(`${isBlocking?'Enviar bloqueio':'Liberar veículo'} para ${vehicle.plate}?\n\nEsta ação será registrada na auditoria e enviada ao provedor configurado.`);if(!approved)return;const reason=window.prompt('Informe o motivo do comando:','Ação operacional autorizada');if(reason===null)return;if(liveMode){try{await apiRequest(`/api/vehicles/${encodeURIComponent(id)}/blocker/commands`,{method:'POST',body:JSON.stringify({action:isBlocking?'BLOCK':'UNBLOCK',reason})});await loadLiveData();toast('Comando enviado',`${isBlocking?'Bloqueio':'Liberação'} aceito pela API.`);}catch(error){toast('Comando recusado',error.message);}return;}blockerStates[id]={...device,armed:!isBlocking,command:'pending',last:'agora'};localStorage.setItem('nexus-blocker-states',JSON.stringify(blockerStates));document.getElementById('vehicleDrawer')?.remove();render();toast('Comando local',`${isBlocking?'Bloqueio':'Liberação'} salvo no modo demonstração.`);}
async function toggleIntegration(id){const item=integrations.find(i=>String(i.id)===String(id));if(!item)return;if(liveMode){try{await apiRequest(`/api/integrations/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({enabled:!item.on})});await loadLiveData();toast('Status atualizado',!item.on?'Integração ativada.':'Integração pausada.');}catch(error){toast('Não foi possível atualizar',error.message);}return;}integrations=integrations.map(i=>String(i.id)===String(id)?{...i,on:!i.on,health:!i.on?'Saudável':'Atenção'}:i);localStorage.setItem('nexus-integrations',JSON.stringify(integrations));render();toast('Status atualizado',integrations.find(i=>String(i.id)===String(id)).on?'Integração ativada.':'Integração pausada.');}
function openModal(){document.getElementById('modalBackdrop').hidden=false;document.querySelector('#integrationForm input').focus()}
function closeModal(){document.getElementById('modalBackdrop').hidden=true;document.getElementById('integrationForm').reset()}
function openConnectionModal(){const form=document.getElementById('connectionForm');form.apiUrl.value=apiBase;document.getElementById('connectionModalBackdrop').hidden=false;form.apiUrl.focus();}
function closeConnectionModal(){document.getElementById('connectionModalBackdrop').hidden=true;document.getElementById('connectionForm').reset();}
document.getElementById('sidebarToggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('collapsed'));
document.getElementById('modalClose').addEventListener('click',closeModal);document.getElementById('modalCancel').addEventListener('click',closeModal);document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});document.getElementById('integrationForm').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const payload={name:data.name,provider:data.provider,protocol:data.protocol,baseUrl:data.url||undefined,settings:{positionsEndpoint:data.positions||undefined,interval:data.interval||undefined}};try{if(liveMode){await apiRequest('/api/integrations',{method:'POST',body:JSON.stringify(payload)});await loadLiveData();toast('Integração criada',`${data.name} foi salva no backend.`);}else{integrations.push({id:Date.now(),name:data.name,provider:data.provider,protocol:data.protocol,last:'agora',vehicles:0,on:true,health:'Saudável',baseUrl:data.url||''});localStorage.setItem('nexus-integrations',JSON.stringify(integrations));currentView='integrations';render();toast('Integração local',`${data.name} foi salva neste navegador.`);}closeModal();}catch(error){toast('Não foi possível criar',error.message);}});
document.getElementById('vehicleModalClose').addEventListener('click',closeVehicleModal);document.getElementById('vehicleModalCancel').addEventListener('click',closeVehicleModal);document.getElementById('vehicleModalBackdrop').addEventListener('click',e=>{if(e.target.id==='vehicleModalBackdrop')closeVehicleModal()});document.getElementById('vehicleForm').addEventListener('submit',e=>{e.preventDefault();void saveVehicle(e.target);});
document.getElementById('vehiclePhoto').addEventListener('change',e=>{const file=e.target.files?.[0];const preview=document.getElementById('vehiclePhotoPreview');if(!file){preview.hidden=true;return;}const reader=new FileReader();reader.onload=()=>{preview.querySelector('img').src=String(reader.result);preview.hidden=false;};reader.readAsDataURL(file);});
document.getElementById('driverModalClose').addEventListener('click',closeDriverModal);document.getElementById('driverModalCancel').addEventListener('click',closeDriverModal);document.getElementById('driverModalBackdrop').addEventListener('click',e=>{if(e.target.id==='driverModalBackdrop')closeDriverModal()});document.getElementById('driverForm').addEventListener('submit',e=>{e.preventDefault();void saveDriver(e.target);});
document.getElementById('connectionButton').addEventListener('click',openConnectionModal);document.getElementById('connectionModalClose').addEventListener('click',closeConnectionModal);document.getElementById('connectionModalBackdrop').addEventListener('click',e=>{if(e.target.id==='connectionModalBackdrop')closeConnectionModal()});document.getElementById('connectionDisconnect').addEventListener('click',()=>{accessToken='';apiBase='';liveMode=false;localStorage.removeItem('nexus-access-token');localStorage.removeItem('nexus-api-url');liveSocket?.close();liveSocket=null;closeConnectionModal();updateConnectionChrome();toast('Desconectado','A interface voltou ao modo demonstração.');render();});document.getElementById('connectionForm').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));apiBase=String(data.apiUrl).replace(/\/$/,'');try{const result=await apiRequest('/api/auth/login',{method:'POST',body:JSON.stringify({tenantSlug:data.tenantSlug,email:data.email,password:data.password})});accessToken=result.token;liveMode=true;localStorage.setItem('nexus-api-url',apiBase);localStorage.setItem('nexus-access-token',accessToken);closeConnectionModal();await loadLiveData({notify:true});toast('Backend conectado','O ambiente multi-tenant está ativo neste navegador.');}catch(error){accessToken='';liveMode=false;toast('Falha no login',error.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('vehicleDrawer')?.remove();if(!document.getElementById('modalBackdrop').hidden)closeModal();if(!document.getElementById('vehicleModalBackdrop').hidden)closeVehicleModal();if(!document.getElementById('driverModalBackdrop').hidden)closeDriverModal();if(!document.getElementById('connectionModalBackdrop').hidden)closeConnectionModal()}});
updateConnectionChrome();
render();
if(liveMode)void loadLiveData();

